(window.VILLAGE_DATA=window.VILLAGE_DATA||{})["cirque"]={"building": "cirque", "name": "Le Chapiteau du Cirque", "main": "cirque", "roomList": [{"key": "cirque", "short": "La piste"}, {"key": "clowns", "short": "Les clowns"}, {"key": "menagerie", "short": "La ménagerie"}, {"key": "trapezes", "short": "Les trapèzes"}, {"key": "parade", "short": "La parade"}, {"key": "magie", "short": "La magie"}, {"key": "surprises", "short": "Les surprises"}], "rooms": {"cirque": {"name": "Le Chapiteau du Cirque", "room_id": "R_adv_manner_01", "image": "cirque/cirque.jpg", "alt": "The circus big top under red-and-yellow stripes, painted in ink and gouache: a four-tier round wooden stand in the ring. On top a ringmaster cracks his whip as flowers spring from the sawdust, a girl balances a strawberry parfait and a poodle hugs a black boot. Below, a strongman cradles a lion cub, another lifts a baby elephant, a seal claps, and a clown's teapot lid pops off in steam. A clown rides a unicycle, a vet with a stethoscope checks a seal, a bandaged clown drops his ice cream into a puddle, and a blindfolded clown walks into a cream pie. A clown springs out of a trapdoor, a ghost makes the audience jump up, and a lion naps in a boat. On the ring rug clowns queue behind a red wagon and a crowd of clowns squeezes into one tiny car. The open tent flap at the far left leads out to the park; a plank door with a red ball on the left, a door with a paw print on the right, and four coloured doors on a balcony reached by a ladder lead to the other rooms; a striped ticket booth stands at the right.", "nameplate": [84, 94], "mapExit": {"box": [1.9531, 15.2778, 13.2812, 56.9444], "label": "Parc des Curiosités", "boxPx": [25, 110, 170, 410]}, "doors": [{"to": "clowns", "label": "Les clowns", "hint": "Go through the plank door with the red ball", "hit": [231, 200, 112, 300], "thumb": "cirque/clowns.jpg"}, {"to": "menagerie", "label": "La ménagerie", "hint": "Go through the door with the paw print", "hit": [968, 244, 118, 250], "thumb": "cirque/menagerie.jpg"}, {"to": "trapezes", "label": "Les trapèzes", "hint": "Climb the ladder to the blue balcony door", "hit": [962, 50, 44, 94], "thumb": "cirque/trapezes.jpg"}, {"to": "parade", "label": "La parade", "hint": "Climb the ladder to the yellow balcony door", "hit": [1025, 50, 48, 94], "thumb": "cirque/parade.jpg"}, {"to": "magie", "label": "La magie", "hint": "Climb the ladder to the red balcony door", "hit": [1087, 50, 52, 94], "thumb": "cirque/magie.jpg"}, {"to": "surprises", "label": "Les surprises", "hint": "Climb the ladder to the green balcony door", "hit": [1168, 50, 52, 94], "thumb": "cirque/surprises.jpg"}], "zooms": [{"to": "cirque_guichet", "label": "le guichet", "hint": "Look closer at the ticket booth", "at": [1185, 335], "obj": [1100, 300, 180, 315]}], "items": [{"id": "fr_immediatement_adv", "adv": true, "fr": "immédiatement", "g": "adv", "en": "immediately", "ipa": "/i.me.djat.mɑ̃/", "say": "ee-may-dyah-tuh-MAHN", "hook": "Like English 'immediately', said ee-may-dyah-tuh-MAHN: the ringmaster cracks her whip and a little flower MEADOW bursts IMMEDIATELY out of the sawdust at her feet.", "note": null, "ex": ["Viens ici immédiatement !", "Come here immediately!"], "box": [32.1875, 1.1111, 10.9375, 21.5278], "label": [37.6562, 1.6667], "labelPx": [396.0, 12, 172, 29], "boxPx": [412, 8, 140, 155], "side": "C", "cardSrc": "cirque/cards/fr_immediatement_adv.webp"}, {"id": "fr_parfaitement_adv", "adv": true, "fr": "parfaitement", "g": "adv", "en": "perfectly", "ipa": "/paʁ.fɛt.mɑ̃/", "say": "pahr-feh-tuh-MAHN", "hook": "Like English 'perfectly', said pahr-feh-tuh-MAHN: a girl balances a towering strawberry parfait (\"pahr-FEH\") on one hand, holding it PERFECTLY still on one leg.", "note": null, "ex": ["Il parle parfaitement anglais.", "He speaks perfect English."], "box": [45.9375, 1.1111, 7.4219, 21.5278], "label": [49.6094, 18.0556], "labelPx": [562.0, 130, 146, 29], "boxPx": [588, 8, 95, 155], "side": "C", "cardSrc": "cirque/cards/fr_parfaitement_adv.webp"}, {"id": "fr_particulierement_adv", "adv": true, "fr": "particulièrement", "g": "adv", "en": "particularly, specifically; especially", "ipa": "/paʁ.ti.ky.ljɛʁ.mɑ̃/", "say": "pahr-tee-kew-lyeh-ruh-MAHN", "hook": "Like English 'particularly', said pahr-tee-kew-lyeh-ruh-MAHN: a picky white poodle is PARTICULARLY fond of one big black boot and hugs it close.", "note": null, "ex": ["Il fait particulièrement chaud aujourd'hui.", "It's particularly hot today."], "box": [56.0938, 3.4722, 8.5938, 19.4444], "label": [62.9688, 1.6667], "labelPx": [714.5, 12, 183, 29], "boxPx": [718, 25, 110, 140], "side": "C", "cardSrc": "cirque/cards/fr_particulierement_adv.webp"}, {"id": "fr_doucement_adv", "adv": true, "fr": "doucement", "g": "adv", "en": "gently, softly", "ipa": "/dus.mɑ̃/", "say": "doo-suh-MAHN", "hook": "\"doo-suh-MAHN\": DEW-SO-MAN — the strongman lifts a dewy rose SO GENTLY that not one drop of DEW falls. doucement = gently.", "note": null, "ex": ["Parle doucement, le bébé dort.", "Speak softly, the baby is sleeping."], "box": [32.6562, 24.7222, 8.4375, 16.9444], "label": [36.875, 25.2778], "labelPx": [408.5, 182, 127, 29], "boxPx": [418, 178, 108, 122], "side": "C", "cardSrc": "cirque/cards/fr_doucement_adv.webp"}, {"id": "fr_facilement_adv", "adv": true, "fr": "facilement", "g": "adv", "en": "easily", "ipa": "/fa.sil.mɑ̃/", "say": "fah-see-luh-MAHN", "hook": "A strongman, a facile man (\"fah-see-luh-MAHN\"), lifts a baby elephant over his head EASILY, smiling.", "note": null, "ex": ["Il a gagné facilement.", "He won easily."], "box": [42.9688, 23.8889, 8.75, 12.2222], "label": [47.3438, 24.4444], "labelPx": [544.5, 176, 123, 29], "boxPx": [550, 172, 112, 88], "side": "C", "cardSrc": "cirque/cards/fr_facilement_adv.webp"}, {"id": "fr_naturellement_adv", "adv": true, "fr": "naturellement", "g": "adv", "en": "naturally", "ipa": "/na.ty.ʁɛl.mɑ̃/", "say": "nah-tew-reh-luh-MAHN", "hook": "Like English 'naturally', said nah-tew-reh-luh-MAHN: a seal claps its flippers NATURALLY, as if it was born to perform.", "note": null, "ex": ["Naturellement, tu es invité.", "Naturally, you're invited."], "box": [52.5, 25.0, 6.0938, 16.3889], "label": [55.5469, 36.9444], "labelPx": [632.0, 266, 158, 29], "boxPx": [672, 180, 78, 118], "side": "C", "cardSrc": "cirque/cards/fr_naturellement_adv.webp"}, {"id": "fr_brusquement_adv", "adv": true, "fr": "brusquement", "g": "adv", "en": "suddenly", "ipa": "/bʁys.kə.mɑ̃/", "say": "brews-kuh-MAHN", "hook": "Like English 'brusquely', said brews-kuh-MAHN: a clown BREWS tea on a drum, and SUDDENLY the teapot lid pops off in a puff of steam.", "note": null, "ex": ["La voiture s'est arrêtée brusquement.", "The car stopped suddenly."], "box": [58.75, 25.0, 10.1562, 11.1111], "label": [66.875, 31.5278], "labelPx": [782.0, 227, 148, 29], "boxPx": [752, 180, 130, 80], "side": "C", "cardSrc": "cirque/cards/fr_brusquement_adv.webp"}, {"id": "fr_rapidement_adv", "adv": true, "fr": "rapidement", "g": "adv", "en": "quickly", "ipa": "/ʁa.pid.mɑ̃/", "say": "rah-pea-duh-MAHN", "hook": "Like English 'rapidly', said rah-pid-MAHN: a unicycling clown zips RAPIDLY round the ring, arms flung wide and coat-tails flying.", "note": null, "ex": ["Il a répondu rapidement.", "He answered quickly."], "box": [29.6875, 41.6667, 9.375, 18.0556], "label": [34.375, 55.1389], "labelPx": [374.0, 397, 132, 29], "boxPx": [380, 300, 120, 130], "side": "C", "cardSrc": "cirque/cards/fr_rapidement_adv.webp"}, {"id": "fr_vite_adv", "adv": true, "fr": "vite", "g": "adv", "en": "quickly", "ipa": "/vit/", "say": "VEET", "hook": "A vet (\"VEET\") rushes QUICKLY over with his stethoscope to check the seal.", "note": null, "ex": ["Viens vite !", "Come quickly!"], "box": [40.0, 43.0556, 11.7188, 17.3611], "label": [45.8594, 38.4722], "labelPx": [558.5, 277, 57, 29], "boxPx": [512, 310, 150, 125], "side": "C", "cardSrc": "cirque/cards/fr_vite_adv.webp"}, {"id": "fr_mal_adv", "adv": true, "fr": "mal", "g": "adv", "en": "badly; (avoir mal = hurt)", "ipa": "/mal/", "say": "MAHL", "hook": "\"MAHL\": the clown's MALL shopping bags burst and his ice cream drops: everything goes BADLY. mal = badly.", "note": null, "ex": ["J'ai mal à la tête.", "I have a headache."], "box": [52.1875, 43.75, 7.4219, 16.6667], "label": [55.8984, 55.8333], "labelPx": [687.0, 402, 57, 29], "boxPx": [668, 315, 95, 120], "side": "C", "cardSrc": "cirque/cards/fr_mal_adv.webp"}, {"id": "fr_directement_adv", "adv": true, "fr": "directement", "g": "adv", "en": "directly", "ipa": "/di.ʁɛk.tə.mɑ̃/", "say": "dee-rehk-tuh-MAHN", "hook": "Like English 'directly', said dee-rehk-tuh-MAHN: a blindfolded clown walks DIRECTLY into the one cream pie on the stand: splat!", "note": null, "ex": ["Rentre directement à la maison après l'école.", "Come straight home after school."], "box": [60.5469, 43.0556, 9.375, 17.3611], "label": [68.0469, 38.4722], "labelPx": [802.0, 277, 138, 29], "boxPx": [775, 310, 120, 125], "side": "C", "cardSrc": "cirque/cards/fr_directement_adv.webp"}, {"id": "fr_soudain_adv", "adv": true, "fr": "soudain", "g": "adv", "en": "suddenly", "ipa": "/su.dɛ̃/", "say": "soo-DAN", "hook": "Like English 'sudden', said soo-DAN: SUDDENLY Dan the clown springs up out of a trapdoor on a coil spring, and his partner Sue squeals \"soo-DAN!\"", "note": null, "ex": ["Soudain, la lumière s'éteint.", "Suddenly, the light goes out."], "box": [29.2969, 63.1944, 9.7656, 13.8889], "label": [34.1797, 72.5], "labelPx": [389.0, 522, 97, 29], "boxPx": [375, 455, 125, 100], "side": "C", "cardSrc": "cirque/cards/fr_soudain_adv.webp"}, {"id": "fr_debout_adv", "adv": true, "fr": "debout", "g": "adv", "en": "standing", "ipa": "/də.bu/", "say": "duh-BOO", "hook": "A ghost shouts \"BOO!\" (\"duh-BOO\") and the whole circus audience jumps up STANDING.", "note": null, "ex": ["Les élèves sont debout.", "The pupils are standing."], "box": [40.0, 63.1944, 17.5781, 13.8889], "label": [48.7891, 72.5], "labelPx": [580.5, 522, 88, 29], "boxPx": [512, 455, 225, 100], "side": "C", "cardSrc": "cirque/cards/fr_debout_adv.webp"}, {"id": "fr_tranquillement_adv", "adv": true, "fr": "tranquillement", "g": "adv", "en": "calmly", "ipa": "/tʁɑ̃.kil.mɑ̃/", "say": "trahn-kee-luh-MAHN", "hook": "Like English 'tranquilly', said trahn-kee-luh-MAHN: a lion naps CALMLY in a little wooden boat, resting his chin on its KEEL-side.", "note": null, "ex": ["Nous marchons tranquillement dans le parc.", "We walk calmly in the park."], "box": [58.9844, 63.1944, 14.8438, 13.8889], "label": [66.4062, 72.5], "labelPx": [767.5, 522, 165, 29], "boxPx": [755, 455, 190, 100], "side": "C", "cardSrc": "cirque/cards/fr_tranquillement_adv.webp"}, {"id": "fr_d_abord_adv", "adv": true, "fr": "d'abord", "g": "adv", "en": "first, at first", "ipa": "/d‿a.bɔʁ/", "say": "dah-BOR", "hook": "\"All ABOARD!\" (\"da-BOR\"): FIRST the red wagon, then the clowns climb on in line, one after the other. FIRST of all comes the wagon.", "note": null, "ex": ["D'abord, on mange, ensuite on joue.", "First we eat, then we play."], "box": [22.0312, 78.0556, 25.7812, 18.75], "label": [34.9219, 94.3056], "labelPx": [400.0, 679, 94, 29], "boxPx": [282, 562, 330, 135], "side": "C", "cardSrc": "cirque/cards/fr_d_abord_adv.webp"}, {"id": "fr_ensemble_adv", "adv": true, "fr": "ensemble", "g": "adv", "en": "together", "ipa": "/ɑ̃.sɑ̃bl/", "say": "ahn-SAHNBL", "hook": "Like English 'ensemble', said ahn-SAHNBL: a whole clown ENSEMBLE squeezes into one tiny striped car TOGETHER.", "note": null, "ex": ["Nous allons au cinéma ensemble.", "We're going to the cinema together."], "box": [48.4375, 78.8889, 15.625, 17.7778], "label": [56.25, 94.3056], "labelPx": [664.0, 679, 112, 29], "boxPx": [620, 568, 200, 128], "side": "C", "cardSrc": "cirque/cards/fr_ensemble_adv.webp"}], "parent": null}, "cirque_guichet": {"name": "Le guichet", "room_id": "R_adv_manner_01_z1", "image": "cirque/cirque_guichet.jpg", "parent": "cirque", "alt": "A close-up of the striped circus ticket booth, painted in ink and gouache, with six cubbies under a scalloped awning: a polka-dot clown grabs his stubbed toe; a bee juggles three balls; a ringmaster points at a juggler with clubs; a boy with a lantern walks behind a snail; a clown dressed as a cabbage stands between two plain clowns; a baker in an apron holds up one cracker. A brass bell and a roll of tickets sit on the counter, with lanterns on either side.", "doors": [], "zooms": [], "items": [{"id": "fr_aussitot_adv", "adv": true, "fr": "aussitôt", "g": "adv", "en": "immediately", "ipa": "/o.si.to/", "say": "oh-see-TOH", "hook": "\"Oh, see toe!\" (\"oh-see-TOH\"): a polka-dot clown stubs his toe and grabs it IMMEDIATELY, hopping on one foot.", "note": null, "ex": ["Il est parti aussitôt après le repas.", "He left immediately after the meal."], "box": [24.375, 15.5556, 11.7188, 27.5], "label": [30.2344, 10.9722], "labelPx": [338.0, 79, 98, 29], "boxPx": [312, 112, 150, 198], "side": "C", "cardSrc": "cirque/cards/fr_aussitot_adv.webp"}, {"id": "fr_bien_adv", "adv": true, "fr": "bien", "g": "adv", "en": "well", "ipa": "/bjɛ̃/", "say": "BYAN", "hook": "A circus bee (\"BYAN\") juggles WELL, three coloured balls in the air and never a drop.", "note": null, "ex": ["Tu chantes très bien.", "You sing very well."], "box": [43.75, 19.4444, 12.5, 22.9167], "label": [50.0, 42.9167], "labelPx": [608.5, 309, 63, 29], "boxPx": [560, 140, 160, 165], "side": "C", "cardSrc": "cirque/cards/fr_bien_adv.webp"}, {"id": "fr_justement_adv", "adv": true, "fr": "justement", "g": "adv", "en": "exactly, precisely", "ipa": "/ʒys.tə.mɑ̃/", "say": "zhews-tuh-MAHN", "hook": "\"JUST the man (\"zhews-tuh-MAHN\") I wanted: EXACTLY!\" says the ringmaster, pointing as the juggler with his clubs arrives.", "note": null, "ex": ["Je voulais justement t'appeler.", "I was just about to call you."], "box": [62.1875, 15.5556, 15.3125, 27.5], "label": [69.8438, 10.9722], "labelPx": [835.5, 79, 117, 29], "boxPx": [796, 112, 196, 198], "side": "C", "cardSrc": "cirque/cards/fr_justement_adv.webp"}, {"id": "fr_lentement_adv", "adv": true, "fr": "lentement", "g": "adv", "en": "slowly", "ipa": "/lɑ̃t.mɑ̃/", "say": "lahn-tuh-MAHN", "hook": "A lantern man (\"lahn-tuh-MAHN\") walks SLOWLY behind a snail, step by tiny step.", "note": null, "ex": ["Parle plus lentement, s'il te plaît.", "Speak more slowly, please."], "box": [22.6562, 45.1389, 15.625, 26.3889], "label": [30.4688, 72.0833], "labelPx": [330.5, 519, 119, 29], "boxPx": [290, 325, 200, 190], "side": "C", "cardSrc": "cirque/cards/fr_lentement_adv.webp"}, {"id": "fr_notamment_adv", "adv": true, "fr": "notamment", "g": "adv", "en": "notably", "ipa": "/nɔ.ta.mɑ̃/", "say": "noh-tah-MAHN", "hook": "Like English 'notably', said noh-tah-MAHN: between two plain clowns one stands out NOTABLY: NO TAM o'shanter, MAN, he is dressed as a cabbage.", "note": null, "ex": ["J'aime les fruits, notamment les pommes.", "I like fruit, notably apples."], "box": [41.0156, 47.9167, 18.3594, 22.9167], "label": [50.1953, 71.3889], "labelPx": [577.0, 514, 131, 29], "boxPx": [525, 345, 235, 165], "side": "C", "cardSrc": "cirque/cards/fr_notamment_adv.webp"}, {"id": "fr_simplement_adv", "adv": true, "fr": "simplement", "g": "adv", "en": "simply", "ipa": "/sɛ̃.plə.mɑ̃/", "say": "san-pluh-MAHN", "hook": "Like English 'simply', said san-pluh-MAHN: a SAMPLE MAN in an apron SIMPLY holds up one cracker, proud as anything.", "note": null, "ex": ["Il a répondu simplement.", "He answered simply."], "box": [63.125, 45.1389, 13.4375, 26.3889], "label": [69.8438, 72.0833], "labelPx": [827.0, 519, 134, 29], "boxPx": [808, 325, 172, 190], "side": "C", "cardSrc": "cirque/cards/fr_simplement_adv.webp"}]}, "clowns": {"name": "Les clowns", "room_id": "R_adv_manner_02", "image": "cirque/clowns.jpg", "backTo": "cirque", "alt": "The clowns' dressing room of the big top, painted in ink and gouache, with a mirror ringed with bulbs and a rack of costumes on the right and a round stand in the middle: a scales-man juggles, a swan balances an egg on its head, and a clown saws at a viola as his hat flies off. A girl waves a flag, a seal raises a flipper by a clown with a hoop, and a puppy watches from a little tent. A clown hides a pie as the ringmaster looks away, a dour coach whistles at clowns doing press-ups, and a clown holds an umbrella over a granny. On the floor three seals balance beach balls, a grey elephant walks a low rope and a mime tiptoes. An open costume trunk full of little compartments sits at the bottom right. The plank door with the red ball on the left leads back to the ring.", "nameplate": [16, 5], "doors": [{"to": "cirque", "label": "Le Chapiteau du Cirque", "hint": "Go back through the plank door with the red ball to the ring", "hit": [45, 150, 170, 370], "thumb": "cirque/cirque.jpg"}], "zooms": [{"to": "clowns_malle", "label": "la malle", "hint": "Look closer at the costume trunk", "at": [1135, 455], "obj": [1015, 440, 245, 255]}], "items": [{"id": "fr_librement_adv", "adv": true, "fr": "librement", "g": "adv", "en": "freely", "ipa": "/li.bʁə.mɑ̃/", "say": "lee-bruh-MAHN", "hook": "LIBRA (\"lee-bruh-MAHN\"), the scales-man, juggles FREELY above his balancing scales, free as LIBERTY.", "note": null, "ex": ["Les animaux circulent librement dans le parc.", "The animals roam freely in the park."], "box": [28.9062, 2.7778, 12.1094, 20.8333], "label": [34.9609, 1.6667], "labelPx": [390.0, 12, 115, 29], "boxPx": [370, 20, 155, 150], "side": "C", "cardSrc": "cirque/cards/fr_librement_adv.webp"}, {"id": "fr_soigneusement_adv", "adv": true, "fr": "soigneusement", "g": "adv", "en": "carefully", "ipa": "/swa.ɲøz.mɑ̃/", "say": "swah-nyeuh-zuh-MAHN", "hook": "A swan (\"swah-nyeuh-zuh-MAHN\") CAREFULLY balances an egg on top of its head.", "note": null, "ex": ["Il range soigneusement ses affaires.", "He puts his things away carefully."], "box": [44.9219, 2.0833, 8.9844, 21.5278], "label": [48.0469, 19.5833], "labelPx": [532.0, 141, 166, 29], "boxPx": [575, 15, 115, 155], "side": "C", "cardSrc": "cirque/cards/fr_soigneusement_adv.webp"}, {"id": "fr_violemment_adv", "adv": true, "fr": "violemment", "g": "adv", "en": "violently", "ipa": "/vjɔ.la.mɑ̃/", "say": "vyoh-lah-MAHN", "hook": "Hear VIOLA in it (\"vyoh-lah-MAHN\"): a clown saws at his viola so VIOLENTLY that his hat flies off.", "note": null, "ex": ["Le vent souffle violemment.", "The wind is blowing violently."], "box": [55.0781, 1.3889, 12.8906, 22.2222], "label": [61.5234, 1.6667], "labelPx": [721.0, 12, 133, 29], "boxPx": [705, 10, 165, 160], "side": "C", "cardSrc": "cirque/cards/fr_violemment_adv.webp"}, {"id": "fr_vivement_adv", "adv": true, "fr": "vivement", "g": "adv", "en": "keenly", "ipa": "/viv.mɑ̃/", "say": "vee-vuh-MAHN", "hook": "Like English 'vividly', said vee-vuh-MAHN: a girl KEENLY waves her flag at the ring, cheering \"VIVE!\" at every trick.", "note": null, "ex": ["Vivement les vacances !", "Roll on the holidays!"], "box": [26.9531, 27.0833, 9.7656, 19.4444], "label": [31.8359, 41.9444], "labelPx": [353.5, 302, 108, 29], "boxPx": [345, 195, 125, 140], "side": "C", "cardSrc": "cirque/cards/fr_vivement_adv.webp"}, {"id": "fr_volontiers_adv", "adv": true, "fr": "volontiers", "g": "adv", "en": "gladly", "ipa": "/vɔ.lɔ̃.tje/", "say": "voh-lohn-TYAY", "hook": "Like English 'volunteer', said voh-lohn-TYAY: a seal GLADLY VOLUNTEERS, flipper raised and a ball on its nose, while the clown holds up the hoop.", "note": null, "ex": ["Je viendrai volontiers.", "I'll gladly come."], "box": [39.4531, 27.0833, 8.9844, 19.4444], "label": [43.9453, 41.9444], "labelPx": [504.0, 302, 117, 29], "boxPx": [505, 195, 115, 140], "side": "C", "cardSrc": "cirque/cards/fr_volontiers_adv.webp"}, {"id": "fr_attentivement_adv", "adv": true, "fr": "attentivement", "g": "adv", "en": "attentively", "ipa": "/a.tɑ̃.tiv.mɑ̃/", "say": "ah-tahn-tee-vuh-MAHN", "hook": "Like English 'attentively', said ah-tahn-tee-vuh-MAHN: a puppy watches ATTENTIVELY from the door of a little circus TENT, eyes on the juggling balls.", "note": null, "ex": ["Écoutez attentivement la question.", "Listen carefully to the question."], "box": [60.9375, 26.3889, 10.1562, 20.1389], "label": [66.0156, 41.9444], "labelPx": [767.5, 302, 155, 29], "boxPx": [780, 190, 130, 145], "side": "C", "cardSrc": "cirque/cards/fr_attentivement_adv.webp"}, {"id": "fr_discretement_adv", "adv": true, "fr": "discrètement", "g": "adv", "en": "discreetly, discretely", "ipa": "/dis.kʁɛt.mɑ̃/", "say": "dees-kreh-tuh-MAHN", "hook": "Like English 'discreetly', said dees-kreh-tuh-MAHN: a clown hides a cream pie DISCREETLY behind him while the ringmaster looks the other way.", "note": null, "ex": ["Il quitte la salle discrètement.", "He leaves the room discreetly."], "box": [23.4375, 48.6111, 14.0625, 17.3611], "label": [30.4688, 66.5278], "labelPx": [316.5, 479, 147, 29], "boxPx": [300, 350, 180, 125], "side": "C", "cardSrc": "cirque/cards/fr_discretement_adv.webp"}, {"id": "fr_durement_adv", "adv": true, "fr": "durement", "g": "adv", "en": "sternly, harshly; with difficulty", "ipa": "/dyʁ.mɑ̃/", "say": "dew-ruh-MAHN", "hook": "A dour man (\"dur-MON\") coaches HARSHLY, blowing his whistle as the clowns do press-ups.", "note": null, "ex": ["Il a travaillé durement toute sa vie.", "He worked hard all his life."], "box": [39.0625, 48.6111, 20.7031, 20.8333], "label": [49.4141, 64.8611], "labelPx": [575.0, 467, 115, 29], "boxPx": [500, 350, 265, 150], "side": "C", "cardSrc": "cirque/cards/fr_durement_adv.webp"}, {"id": "fr_gentiment_adv", "adv": true, "fr": "gentiment", "g": "adv", "en": "friendly, kindly", "ipa": "/ʒɑ̃.ti.mɑ̃/", "say": "zhahn-tee-MAHN", "hook": "A gentle (\"zhon-tee\") clown KINDLY holds his umbrella over a granny and helps her along.", "note": null, "ex": ["Il m'a gentiment aidé.", "He kindly helped me."], "box": [60.5469, 48.6111, 12.8906, 20.1389], "label": [66.9922, 64.1667], "labelPx": [797.5, 462, 120, 29], "boxPx": [775, 350, 165, 145], "side": "C", "cardSrc": "cirque/cards/fr_gentiment_adv.webp"}, {"id": "fr_joyeusement_adv", "adv": true, "fr": "joyeusement", "g": "adv", "en": "joyfully, joyously", "ipa": "/ʒwa.jøz.mɑ̃/", "say": "zhwah-yeuh-zuh-MAHN", "hook": "Like English 'joyously', said zhwah-yeuh-zuh-MAHN: three seals balance beach balls JOYFULLY on their noses.", "note": null, "ex": ["Les enfants chantent joyeusement.", "The children sing joyfully."], "box": [18.75, 71.5278, 23.4375, 25.0], "label": [30.4688, 94.3056], "labelPx": [319.5, 679, 141, 29], "boxPx": [240, 515, 300, 180], "side": "C", "cardSrc": "cirque/cards/fr_joyeusement_adv.webp"}, {"id": "fr_progressivement_adv", "adv": true, "fr": "progressivement", "g": "adv", "en": "progressively", "ipa": "/pʁɔ.ɡʁɛ.siv.mɑ̃/", "say": "proh-gray-see-vuh-MAHN", "hook": "Like English 'progressively', said proh-gray-see-vuh-MAHN: a GREY elephant edges along a low tightrope PROGRESSIVELY, one careful step after another.", "note": null, "ex": ["Le temps s'améliore progressivement.", "The weather is gradually improving."], "box": [46.0938, 72.2222, 17.1875, 23.6111], "label": [54.6875, 94.3056], "labelPx": [609.5, 679, 181, 29], "boxPx": [590, 520, 220, 170], "side": "C", "cardSrc": "cirque/cards/fr_progressivement_adv.webp"}, {"id": "fr_silencieusement_adv", "adv": true, "fr": "silencieusement", "g": "adv", "en": "silently", "ipa": "/si.lɑ̃.sjøz.mɑ̃/", "say": "see-lahn-syeuh-zuh-MAHN", "hook": "Like English 'silently', said see-lahn-syeuh-zuh-MAHN: a white-faced mime tiptoes SILENTLY across the ring, not a sound.", "note": null, "ex": ["Le chat entre silencieusement.", "The cat comes in silently."], "box": [65.2344, 70.1389, 9.375, 25.6944], "label": [72.7344, 94.3056], "labelPx": [842.5, 679, 177, 29], "boxPx": [835, 505, 120, 185], "side": "C", "cardSrc": "cirque/cards/fr_silencieusement_adv.webp"}], "parent": null}, "clowns_malle": {"name": "La malle", "room_id": "R_adv_manner_02_z1", "image": "cirque/clowns_malle.jpg", "parent": "clowns", "alt": "A close-up of the open costume trunk in the clowns' room, painted in ink and gouache, with six compartments: a clown reads a short scroll; a clown sits cross-legged by a bowl of still water; a frail old man lifts a teacup in both hands; a clown clips a poodle-shaped hedge; a man in a flat cap fishes in a bucket with one goldfish; a clown hugs a sleepy kitten.", "doors": [], "zooms": [], "items": [{"id": "fr_bref_adv", "adv": true, "fr": "bref", "g": "adv", "en": "in short, in brief, briefly", "ipa": "/bʁɛf/", "say": "BREHF", "hook": "Like English 'brief', said BREHF: IN SHORT, the clown's speech is a scroll one line long, read in one BREATH.", "note": null, "ex": ["Bref, tout s'est bien passé.", "In short, everything went well."], "box": [23.4375, 22.9167, 13.2812, 25.0], "label": [30.0781, 18.3333], "labelPx": [355.0, 132, 60, 29], "boxPx": [300, 165, 170, 180], "side": "C", "cardSrc": "cirque/cards/fr_bref_adv.webp"}, {"id": "fr_calmement_adv", "adv": true, "fr": "calmement", "g": "adv", "en": "calmly", "ipa": "/kal.mə.mɑ̃/", "say": "kahl-muh-MAHN", "hook": "A calm man (\"kahl-muh-MAHN\") sits cross-legged and breathes CALMLY beside a bowl of perfectly still water.", "note": null, "ex": ["Il répond calmement.", "He answers calmly."], "box": [39.8438, 22.2222, 17.1875, 25.0], "label": [48.4375, 17.6389], "labelPx": [556.5, 127, 127, 29], "boxPx": [510, 160, 220, 180], "side": "C", "cardSrc": "cirque/cards/fr_calmement_adv.webp"}, {"id": "fr_faiblement_adv", "adv": true, "fr": "faiblement", "g": "adv", "en": "weakly; slightly; mildly", "ipa": "/fɛ.blə.mɑ̃/", "say": "feh-bluh-MAHN", "hook": "A feeble old man (\"feh-bluh-MON\") lifts his teacup WEAKLY in both hands.", "note": null, "ex": ["La lampe éclaire faiblement la pièce.", "The lamp dimly lights the room."], "box": [62.5, 22.2222, 14.0625, 25.0], "label": [69.5312, 17.6389], "labelPx": [828.0, 127, 124, 29], "boxPx": [800, 160, 180, 180], "side": "C", "cardSrc": "cirque/cards/fr_faiblement_adv.webp"}, {"id": "fr_nettement_adv", "adv": true, "fr": "nettement", "g": "adv", "en": "neatly, cleanly, clearly", "ipa": "/nɛtəmɑ̃/", "say": "neh-tuh-MAHN", "hook": "A neat man (\"net-MON\") clips a poodle-shaped hedge NEATLY, every leaf in line.", "note": null, "ex": ["Il va nettement mieux.", "He's much better."], "box": [23.4375, 49.3056, 13.2812, 27.7778], "label": [30.0781, 77.6389], "labelPx": [325.0, 559, 120, 29], "boxPx": [300, 355, 170, 200], "side": "C", "cardSrc": "cirque/cards/fr_nettement_adv.webp"}, {"id": "fr_patiemment_adv", "adv": true, "fr": "patiemment", "g": "adv", "en": "patiently", "ipa": "/pa.sja.mɑ̃/", "say": "pah-syah-MAHN", "hook": "Like English 'patiently', said pah-syah-MAHN: PA in his flat cap fishes PATIENTLY in a bucket with one goldfish, waiting and waiting.", "note": null, "ex": ["Il attend patiemment son tour.", "He waits patiently for his turn."], "box": [39.8438, 49.3056, 19.5312, 27.7778], "label": [49.6094, 77.6389], "labelPx": [566.5, 559, 137, 29], "boxPx": [510, 355, 250, 200], "side": "C", "cardSrc": "cirque/cards/fr_patiemment_adv.webp"}, {"id": "fr_tendrement_adv", "adv": true, "fr": "tendrement", "g": "adv", "en": "tenderly; lovingly", "ipa": "/tɑ̃.dʁə.mɑ̃/", "say": "tahn-druh-MAHN", "hook": "A tender clown (\"tahn-druh-MAHN\") hugs a sleepy kitten TENDERLY.", "note": null, "ex": ["La mère embrasse tendrement son bébé.", "The mother kisses her baby tenderly."], "box": [62.5, 49.3056, 14.8438, 27.7778], "label": [69.9219, 77.6389], "labelPx": [828.5, 559, 133, 29], "boxPx": [800, 355, 190, 200], "side": "C", "cardSrc": "cirque/cards/fr_tendrement_adv.webp"}]}, "menagerie": {"name": "La ménagerie", "room_id": "R_adv_manner_03", "image": "cirque/menagerie.jpg", "backTo": "cirque", "alt": "The animal room of the big top, painted in ink and gouache, with a tall wooden wardrobe on the right and a round stand in the middle: an elephant squeezes through a small hoop, a hippo overflows a tiny bath, and a monkey's plates crash around him. A seal splashes its soaked keeper, a lion sneezes as curtains swing open, and a bear bashes a drum. A clown with a lantern hunts for his red nose, which a seal is wearing; a giraffe with a bandaged neck sees the vet; a girl hands balloons to penguins; and a monkey does handstands by a fizzy bottle. On the floor a lion walks a red carpet and a prince and his poodle sit in a ticket booth. The door with the paw print on the left leads back to the ring.", "nameplate": [16, 5], "doors": [{"to": "cirque", "label": "Le Chapiteau du Cirque", "hint": "Go back through the door with the paw print to the ring", "hit": [44, 148, 172, 370], "thumb": "cirque/cirque.jpg"}], "zooms": [{"to": "menagerie_armoire", "label": "l'armoire", "hint": "Look closer at the animal wardrobe", "at": [1120, 160], "obj": [975, 140, 290, 420]}], "items": [{"id": "fr_difficilement_adv", "adv": true, "fr": "difficilement", "g": "adv", "en": "with difficulty; difficultly", "ipa": "/di.fi.sil.mɑ̃/", "say": "dee-fee-see-luh-MAHN", "hook": "Like English 'with difficulty', said dee-fee-see-luh-MAHN: an elephant squeezes WITH DIFFICULTY through a hoop meant for poodles.", "note": null, "ex": ["Il marche difficilement.", "He walks with difficulty."], "box": [25.3906, 4.8611, 16.0156, 20.1389], "label": [33.3984, 25.5556], "labelPx": [356.0, 184, 143, 29], "boxPx": [325, 35, 205, 145], "side": "C", "cardSrc": "cirque/cards/fr_difficilement_adv.webp"}, {"id": "fr_largement_adv", "adv": true, "fr": "largement", "g": "adv", "en": "largely", "ipa": "/laʁ.ʒə.mɑ̃/", "say": "lahr-zhuh-MAHN", "hook": "Not \"largely\" in sound: largement (lahr-zhuh-MAHN) means WIDELY, AMPLY; a LARGE hippo overflows a tiny bathtub on all sides.", "note": null, "ex": ["Nous avons largement le temps.", "We have plenty of time."], "box": [42.1875, 4.1667, 14.0625, 20.8333], "label": [49.2188, 1.6667], "labelPx": [570.0, 12, 120, 29], "boxPx": [540, 30, 180, 150], "side": "C", "cardSrc": "cirque/cards/fr_largement_adv.webp"}, {"id": "fr_terriblement_adv", "adv": true, "fr": "terriblement", "g": "adv", "en": "terribly", "ipa": "/tɛ.ʁi.blə.mɑ̃/", "say": "teh-ree-bluh-MAHN", "hook": "Like English 'terribly', said teh-ree-bluh-MAHN: a monkey juggles plates TERRIBLY, and they crash and smash all around him.", "note": null, "ex": ["Il fait terriblement chaud.", "It's terribly hot."], "box": [56.4062, 1.3889, 14.0625, 23.6111], "label": [63.4375, 1.6667], "labelPx": [740.5, 12, 143, 29], "boxPx": [722, 10, 180, 170], "side": "C", "cardSrc": "cirque/cards/fr_terriblement_adv.webp"}, {"id": "fr_forcement_adv", "adv": true, "fr": "forcément", "g": "adv", "en": "necessarily", "ipa": "/fɔʁ.se.mɑ̃/", "say": "for-say-MAHN", "hook": "NECESSARILY wet: the keeper stands right by the splashing seal \"for sure, man\" (\"for-say-MON\"), so he is NECESSARILY soaked.", "note": null, "ex": ["Ce n'est pas forcément vrai.", "It's not necessarily true."], "box": [23.4375, 31.25, 21.875, 18.0556], "label": [27.8125, 44.7222], "labelPx": [296.5, 322, 119, 29], "boxPx": [300, 225, 280, 130], "side": "C", "cardSrc": "cirque/cards/fr_forcement_adv.webp"}, {"id": "fr_automatiquement_adv", "adv": true, "fr": "automatiquement", "g": "adv", "en": "automatically", "ipa": "/o.tɔ.ma.tik.mɑ̃/", "say": "oh-toh-mah-tee-kuh-MAHN", "hook": "Like English 'automatically', said oh-toh-mah-tee-kuh-MAHN: the curtains swing open AUTOMATICALLY every time the lion sneezes.", "note": null, "ex": ["La lumière s'allume automatiquement.", "The light comes on automatically."], "box": [46.25, 29.8611, 13.2812, 19.4444], "label": [53.5156, 44.7222], "labelPx": [589.5, 322, 191, 29], "boxPx": [592, 215, 170, 140], "side": "C", "cardSrc": "cirque/cards/fr_automatiquement_adv.webp"}, {"id": "fr_brutalement_adv", "adv": true, "fr": "brutalement", "g": "adv", "en": "brutally", "ipa": "/bʁy.tal.mɑ̃/", "say": "brew-tah-luh-MAHN", "hook": "Like English 'brutally', said brew-tah-luh-MAHN: a BRUTE of a bear bashes the drum BRUTALLY, sticks flying.", "note": null, "ex": ["La voiture a freiné brutalement.", "The car braked sharply."], "box": [61.3281, 27.0833, 10.3906, 21.5278], "label": [66.5234, 27.6389], "labelPx": [781.5, 199, 140, 29], "boxPx": [785, 195, 133, 155], "side": "C", "cardSrc": "cirque/cards/fr_brutalement_adv.webp"}, {"id": "fr_desesperement_adv", "adv": true, "fr": "désespérément", "g": "adv", "en": "desperately", "ipa": "/de.zɛs.pe.ʁe.mɑ̃/", "say": "day-zehs-pay-ray-MAHN", "hook": "Like English 'desperately', said day-zehs-pay-ray-MAHN: RAY the clown searches DESPERATELY with a lantern for his red nose, and the seal beside him is wearing it.", "note": null, "ex": ["Il cherche désespérément ses clés.", "He's desperately looking for his keys."], "box": [24.2188, 50.0, 11.7188, 21.5278], "label": [26.5625, 66.9444], "labelPx": [257.0, 482, 166, 29], "boxPx": [310, 360, 150, 155], "side": "C", "cardSrc": "cirque/cards/fr_desesperement_adv.webp"}, {"id": "fr_gravement_adv", "adv": true, "fr": "gravement", "g": "adv", "en": "seriously, badly", "ipa": "/ɡʁav.mɑ̃/", "say": "grah-vuh-MAHN", "hook": "A giraffe is SERIOUSLY hurt, its neck in bandages, and a grave (\"grav\") vet hurries to help.", "note": null, "ex": ["Il est gravement malade.", "He is seriously ill."], "box": [36.3281, 49.3056, 12.5, 22.2222], "label": [42.5781, 66.9444], "labelPx": [483.5, 482, 123, 29], "boxPx": [465, 355, 160, 160], "side": "C", "cardSrc": "cirque/cards/fr_gravement_adv.webp"}, {"id": "fr_personnellement_adv", "adv": true, "fr": "personnellement", "g": "adv", "en": "personally; as far as I'm concerned", "ipa": "/pɛʁ.sɔ.nɛl.mɑ̃/", "say": "pehr-soh-neh-luh-MAHN", "hook": "Like English 'personally', said pehr-soh-neh-luh-MAHN: NELL PERSONALLY hands each penguin its own balloon.", "note": null, "ex": ["Personnellement, je préfère le thé.", "Personally, I prefer tea."], "box": [49.375, 50.6944, 15.625, 20.8333], "label": [57.1875, 66.9444], "labelPx": [641.0, 482, 182, 29], "boxPx": [632, 365, 200, 150], "side": "C", "cardSrc": "cirque/cards/fr_personnellement_adv.webp"}, {"id": "fr_physiquement_adv", "adv": true, "fr": "physiquement", "g": "adv", "en": "physically", "ipa": "/fizikəmɑ̃/", "say": "fee-zee-kuh-MAHN", "hook": "Like English 'physically', said fee-zee-kuh-MAHN: a monkey gulps a FIZZY lemonade and is PHYSICALLY unable to stop doing handstands.", "note": null, "ex": ["Il est physiquement en forme.", "He is physically fit."], "box": [65.2344, 48.6111, 9.375, 23.6111], "label": [72.7344, 67.6389], "labelPx": [853.0, 487, 156, 29], "boxPx": [835, 350, 120, 170], "side": "C", "cardSrc": "cirque/cards/fr_physiquement_adv.webp"}, {"id": "fr_premierement_adv", "adv": true, "fr": "premièrement", "g": "adv", "en": "firstly; in the first place", "ipa": "/pʁə.mjɛʁ.mɑ̃/", "say": "preuh-myeh-ruh-MAHN", "hook": "FIRSTLY, at the circus premiere (\"pruh-MYAIR\"), the lion walks the red carpet FIRST.", "note": null, "ex": ["Premièrement, lisez la question.", "Firstly, read the question."], "box": [25.7812, 72.2222, 18.3594, 23.6111], "label": [34.9609, 94.3056], "labelPx": [369.0, 679, 157, 29], "boxPx": [330, 520, 235, 170], "side": "C", "cardSrc": "cirque/cards/fr_premierement_adv.webp"}, {"id": "fr_principalement_adv", "adv": true, "fr": "principalement", "g": "adv", "en": "mainly, principally", "ipa": "/pʁɛ̃.si.pal.mɑ̃/", "say": "pran-see-pah-luh-MAHN", "hook": "Like English 'principally', said pran-see-pah-luh-MAHN: the circus is MAINLY run by a PRINCE and his PAL the poodle, side by side in the ticket booth.", "note": null, "ex": ["Il lit principalement des romans.", "He reads mainly novels."], "box": [60.5469, 72.9167, 12.5, 26.3889], "label": [66.7969, 94.3056], "labelPx": [771.5, 679, 167, 29], "boxPx": [775, 525, 160, 190], "side": "C", "cardSrc": "cirque/cards/fr_principalement_adv.webp"}], "parent": null}, "menagerie_armoire": {"name": "L'armoire", "room_id": "R_adv_manner_03_z1", "image": "cirque/menagerie_armoire.jpg", "parent": "menagerie", "alt": "A close-up of the wooden wardrobe in the animal room, painted in ink and gouache, with six shelves: a parrot picks yellow sweets from a jar; a cat stares at a goldfish bowl; a sloth sways in a hammock; a sea lion has a fish cake with one candle; a bee in a top hat rides a unicycle; a monkey grins aboard a red express train.", "doors": [], "zooms": [], "items": [{"id": "fr_uniquement_adv", "adv": true, "fr": "uniquement", "g": "adv", "en": "uniquely; only; exclusively; solely", "ipa": "/y.nik.mɑ̃/", "say": "ew-nee-kuh-MAHN", "hook": "Like English 'uniquely', said ew-nee-kuh-MAHN: a parrot eats ONLY the yellow sweets from the jar, picking them out one by one.", "note": null, "ex": ["Ce magasin vend uniquement du thé.", "This shop sells only tea."], "box": [33.2031, 13.1944, 15.2344, 26.3889], "label": [40.8203, 8.6111], "labelPx": [454.0, 62, 137, 29], "boxPx": [425, 95, 195, 190], "side": "C", "cardSrc": "cirque/cards/fr_uniquement_adv.webp"}, {"id": "fr_fixement_adv", "adv": true, "fr": "fixement", "g": "adv", "en": "fixedly", "ipa": "/fik.sə.mɑ̃/", "say": "feek-suh-MAHN", "hook": "A fixed stare (\"feek-suh-MAHN\"): a cat stares FIXEDLY at a goldfish bowl.", "note": null, "ex": ["Le chat me regarde fixement.", "The cat stares at me."], "box": [50.0, 13.1944, 15.625, 26.3889], "label": [57.8125, 8.6111], "labelPx": [688.0, 62, 104, 29], "boxPx": [640, 95, 200, 190], "side": "C", "cardSrc": "cirque/cards/fr_fixement_adv.webp"}, {"id": "fr_legerement_adv", "adv": true, "fr": "légèrement", "g": "adv", "en": "slightly", "ipa": "/le.ʒɛʁ.mɑ̃/", "say": "lay-zheh-ruh-MAHN", "hook": "A LEISURE-loving sloth (\"lay-zhair-MON\") in a hammock sways ever so SLIGHTLY.", "note": null, "ex": ["Il est légèrement en retard.", "He's slightly late."], "box": [33.2031, 41.6667, 15.2344, 22.9167], "label": [40.8203, 60.0], "labelPx": [457.5, 432, 130, 29], "boxPx": [425, 300, 195, 165], "side": "C", "cardSrc": "cirque/cards/fr_legerement_adv.webp"}, {"id": "fr_specialement_adv", "adv": true, "fr": "spécialement", "g": "adv", "en": "especially, specially", "ipa": "/spe.sjal.mɑ̃/", "say": "spay-syah-luh-MAHN", "hook": "Like English 'specially', said spay-syah-luh-MAHN: a sea lion is given a fish cake with one candle, made SPECIALLY for him.", "note": null, "ex": ["J'ai fait ce gâteau spécialement pour toi.", "I made this cake especially for you."], "box": [50.0, 41.6667, 15.625, 22.9167], "label": [57.8125, 60.0], "labelPx": [666.0, 432, 148, 29], "boxPx": [640, 300, 200, 165], "side": "C", "cardSrc": "cirque/cards/fr_specialement_adv.webp"}, {"id": "fr_bizarrement_adv", "adv": true, "fr": "bizarrement", "g": "adv", "en": "bizarrely", "ipa": "/bi.zaʁ.mɑ̃/", "say": "bee-zah-ruh-MAHN", "hook": "Like English 'bizarrely', said bee-zah-ruh-MAHN: a bee in a top hat rides a unicycle, behaving most BIZARRELY for a bee.", "note": null, "ex": ["Bizarrement, personne n'est venu.", "Oddly, nobody came."], "box": [34.375, 66.6667, 14.0625, 22.9167], "label": [41.4062, 90.1389], "labelPx": [461.0, 649, 138, 29], "boxPx": [440, 480, 180, 165], "side": "C", "cardSrc": "cirque/cards/fr_bizarrement_adv.webp"}, {"id": "fr_expres_adv", "adv": true, "fr": "exprès", "g": "adv", "en": "on purpose, intentionally, deliberately", "ipa": "/ɛk.spʁɛ/", "say": "ehk-SPREH", "hook": "ON PURPOSE, a monkey hops onto the red express (\"eks-PRESS\") train, grinning.", "note": null, "ex": ["Je ne l'ai pas fait exprès !", "I didn't do it on purpose!"], "box": [50.0, 66.6667, 15.625, 22.9167], "label": [57.8125, 90.1389], "labelPx": [698.0, 649, 84, 29], "boxPx": [640, 480, 200, 165], "side": "C", "cardSrc": "cirque/cards/fr_expres_adv.webp"}]}, "trapezes": {"name": "Les trapèzes", "room_id": "R_adv_manner_04", "image": "cirque/trapezes.jpg", "backTo": "cirque", "alt": "The trapeze loft of the big top, painted in ink and gouache, with rolled mats on the right and a round stand in the middle: a baker tosses buns to children, a clown dives into a tub of custard, and a poodle follows the ringmaster. A man leaps in front of a picture of a garden folly, a jolly man arranges flowers, a shy lion cub peeks from behind a red curtain, and a bear juggles on a unicycle. A man offers a girl a rose by a warm stove, a swimmer glides, elephants bounce on a sturdy net, and a carpenter carves a wooden swan. On the floor a lion holds up a hoop, a clown tumbles from smashed stilts, a strongwoman holds a ladder with an acrobat on top, and a dog looks up at her. The blue door on the left leads back to the ring.", "nameplate": [88, 95], "doors": [{"to": "cirque", "label": "Le Chapiteau du Cirque", "hint": "Go back through the blue door to the ring", "hit": [40, 148, 165, 370], "thumb": "cirque/cirque.jpg"}], "zooms": [], "items": [{"id": "fr_abondamment_adv", "adv": true, "fr": "abondamment", "g": "adv", "en": "abundantly, copiously", "ipa": "/a.bɔ̃.da.mɑ̃/", "say": "ah-bohn-dah-MAHN", "hook": "Kids cry \"A BUN, da man!\" (\"ah-bohn-dah-MAHN\") as a jolly baker tosses warm buns ABUNDANTLY from his basket.", "note": null, "ex": ["Il a plu abondamment cette nuit.", "It rained heavily last night."], "box": [25.0, 19.4444, 16.7969, 16.6667], "label": [33.3984, 14.8611], "labelPx": [348.5, 107, 158, 29], "boxPx": [320, 140, 215, 120], "side": "C", "cardSrc": "cirque/cards/fr_abondamment_adv.webp"}, {"id": "fr_courageusement_adv", "adv": true, "fr": "courageusement", "g": "adv", "en": "bravely, courageously, boldly", "ipa": "/ku.ʁa.ʒøz.mɑ̃/", "say": "koo-rah-zheuh-zuh-MAHN", "hook": "Like English 'courageously', said koo-rah-zheuh-zuh-MAHN: a clown dives COURAGEOUSLY into a tub of custard.", "note": null, "ex": ["Il a courageusement sauté à l'eau.", "He bravely jumped into the water."], "box": [43.3594, 15.9722, 11.7188, 18.0556], "label": [49.2188, 34.5833], "labelPx": [540.0, 249, 180, 29], "boxPx": [555, 115, 150, 130], "side": "C", "cardSrc": "cirque/cards/fr_courageusement_adv.webp"}, {"id": "fr_fidelement_adv", "adv": true, "fr": "fidèlement", "g": "adv", "en": "faithfully", "ipa": "/fi.dɛl.mɑ̃/", "say": "fee-deh-luh-MAHN", "hook": "Like English 'faithfully', said fee-deh-luh-MAHN: a poodle follows the ringmaster FAITHFULLY, step for step.", "note": null, "ex": ["Le chien attend fidèlement son maître.", "The dog faithfully waits for its master."], "box": [57.0312, 13.1944, 12.5, 17.3611], "label": [63.2812, 8.6111], "labelPx": [748.5, 62, 123, 29], "boxPx": [730, 95, 160, 125], "side": "C", "cardSrc": "cirque/cards/fr_fidelement_adv.webp"}, {"id": "fr_follement_adv", "adv": true, "fr": "follement", "g": "adv", "en": "madly; insanely", "ipa": "/fɔl.mɑ̃/", "say": "fo-luh-MAHN", "hook": "A man (\"MAHN\") leaps MADLY in front of a picture of a garden folly (\"fo-luh\"), arms flapping.", "note": null, "ex": ["Ils sont follement amoureux.", "They're madly in love."], "box": [23.8281, 38.1944, 13.2812, 17.3611], "label": [30.4688, 50.9722], "labelPx": [333.5, 367, 113, 29], "boxPx": [305, 275, 170, 125], "side": "C", "cardSrc": "cirque/cards/fr_follement_adv.webp"}, {"id": "fr_joliment_adv", "adv": true, "fr": "joliment", "g": "adv", "en": "prettily, cutely; extremely", "ipa": "/ʒɔ.li.mɑ̃/", "say": "zhoh-lee-MAHN", "hook": "A jolly man (\"zhoh-lee-MAHN\") arranges flowers PRETTILY in a vase.", "note": null, "ex": ["La table est joliment décorée.", "The table is prettily decorated."], "box": [38.2812, 39.5833, 10.5469, 17.3611], "label": [43.5547, 52.3611], "labelPx": [507.0, 377, 101, 29], "boxPx": [490, 285, 135, 125], "side": "C", "cardSrc": "cirque/cards/fr_joliment_adv.webp"}, {"id": "fr_timidement_adv", "adv": true, "fr": "timidement", "g": "adv", "en": "timidly; shyly", "ipa": "/timidəmɑ̃/", "say": "tee-mee-duh-MAHN", "hook": "Like English 'timidly', said tee-mee-duh-MAHN: a little lion cub peeks TIMIDLY from behind a red curtain, blushing.", "note": null, "ex": ["L'enfant lève timidement la main.", "The child shyly raises his hand."], "box": [50.7812, 39.5833, 7.8125, 17.3611], "label": [54.6875, 52.3611], "labelPx": [634.0, 377, 132, 29], "boxPx": [650, 285, 100, 125], "side": "C", "cardSrc": "cirque/cards/fr_timidement_adv.webp"}, {"id": "fr_adroitement_adv", "adv": true, "fr": "adroitement", "g": "adv", "en": "adroitly, skilfully", "ipa": "/a.dʁwat.mɑ̃/", "say": "ah-drwah-tuh-MAHN", "hook": "Like English 'adroitly', said ah-drwah-tuh-MAHN: a bear juggles ADROITLY on a unicycle, never dropping a ball.", "note": null, "ex": ["Il a adroitement évité la question.", "He skilfully dodged the question."], "box": [62.5, 35.4167, 10.5469, 20.8333], "label": [67.7734, 51.6667], "labelPx": [798.0, 372, 139, 29], "boxPx": [800, 255, 135, 150], "side": "C", "cardSrc": "cirque/cards/fr_adroitement_adv.webp"}, {"id": "fr_chaleureusement_adv", "adv": true, "fr": "chaleureusement", "g": "adv", "en": "warmly", "ipa": "/ʃa.lœ.ʁøz.mɑ̃/", "say": "shah-leuh-reuh-zuh-MAHN", "hook": "A man offers a rose (\"shah-leuh-REUHZ-mahn\") to a girl beside the warm stove and greets her WARMLY.", "note": null, "ex": ["Ils nous ont accueillis chaleureusement.", "They welcomed us warmly."], "box": [24.2188, 57.2222, 11.7188, 18.4722], "label": [26.5625, 71.1111], "labelPx": [247.0, 512, 186, 29], "boxPx": [310, 412, 150, 133], "side": "C", "cardSrc": "cirque/cards/fr_chaleureusement_adv.webp"}, {"id": "fr_couramment_adv", "adv": true, "fr": "couramment", "g": "adv", "en": "fluently; usually, commonly", "ipa": "/ku.ʁa.mɑ̃/", "say": "koo-rah-MAHN", "hook": "A swimmer glides FLUENTLY with the current (\"koo-ra-MAHN\"), smooth as can be.", "note": null, "ex": ["Elle parle couramment trois langues.", "She speaks three languages fluently."], "box": [36.7188, 61.8056, 12.1094, 13.8889], "label": [42.7734, 71.1111], "labelPx": [476.0, 512, 143, 29], "boxPx": [470, 445, 155, 100], "side": "C", "cardSrc": "cirque/cards/fr_couramment_adv.webp"}, {"id": "fr_durablement_adv", "adv": true, "fr": "durablement", "g": "adv", "en": "durably", "ipa": "/dy.ʁa.blə.mɑ̃/", "say": "dew-rah-bluh-MAHN", "hook": "Like English 'durably', said dew-rah-bluh-MAHN: elephants bounce in a safety net built so DURABLY that it never tears.", "note": null, "ex": ["Ce changement va durablement modifier la ville.", "This change will transform the town for good."], "box": [50.0, 61.8056, 13.6719, 13.8889], "label": [56.8359, 71.1111], "labelPx": [655.5, 512, 144, 29], "boxPx": [640, 445, 175, 100], "side": "C", "cardSrc": "cirque/cards/fr_durablement_adv.webp"}, {"id": "fr_habilement_adv", "adv": true, "fr": "habilement", "g": "adv", "en": "skilfully", "ipa": "/a.bil.mɑ̃/", "say": "ah-bee-luh-MAHN", "hook": "A very ABLE carpenter (\"a-beel-MAHN\") carves a wooden swan SKILFULLY, chips flying.", "note": null, "ex": ["Il conduit habilement dans la neige.", "He drives skilfully in the snow."], "box": [64.8438, 60.4167, 10.1562, 15.2778], "label": [69.9219, 71.1111], "labelPx": [830.0, 512, 130, 29], "boxPx": [830, 435, 130, 110], "side": "C", "cardSrc": "cirque/cards/fr_habilement_adv.webp"}, {"id": "fr_impatiemment_adv", "adv": true, "fr": "impatiemment", "g": "adv", "en": "impatiently", "ipa": "/ɛ̃.pa.sja.mɑ̃/", "say": "an-pah-syah-MAHN", "hook": "Like English 'impatiently', said an-pah-syah-MAHN: a lion holds up his hoop and waits IMPATIENTLY for the act to start.", "note": null, "ex": ["Les enfants attendent impatiemment les vacances.", "The children are waiting impatiently for the holidays."], "box": [23.8281, 77.0833, 12.3438, 21.5278], "label": [26.2969, 94.3056], "labelPx": [256.1, 679, 161, 29], "boxPx": [305, 555, 158, 155], "side": "C", "cardSrc": "cirque/cards/fr_impatiemment_adv.webp"}, {"id": "fr_irremediablement_adv", "adv": true, "fr": "irrémédiablement", "g": "adv", "en": "irrecoverably, irremediably", "ipa": "/i.ʁe.me.dja.blə.mɑ̃/", "say": "ee-ray-may-dyah-bluh-MAHN", "hook": "Like English 'irreparably', said ee-ray-may-dyah-bluh-MAHN: a clown tumbles as his stilts smash into pieces, broken IRREPARABLY.", "note": null, "ex": ["Le vase est irrémédiablement cassé.", "The vase is broken beyond repair."], "box": [36.3281, 78.4722, 10.9375, 18.75], "label": [45.0781, 94.3056], "labelPx": [480.5, 679, 193, 29], "boxPx": [465, 565, 140, 135], "side": "C", "cardSrc": "cirque/cards/fr_irremediablement_adv.webp"}, {"id": "fr_solidement_adv", "adv": true, "fr": "solidement", "g": "adv", "en": "firmly, solidly, securely", "ipa": "/solidəmɑ̃/", "say": "soh-lee-duh-MAHN", "hook": "Like English 'solidly', said soh-lee-duh-MAHN: a strongwoman holds the ladder SOLIDLY while an acrobat stands on top.", "note": null, "ex": ["La corde est solidement attachée.", "The rope is securely tied."], "box": [57.4219, 76.6667, 7.4219, 22.2222], "label": [58.9062, 94.3056], "labelPx": [690.5, 679, 127, 29], "boxPx": [735, 552, 95, 160], "side": "C", "cardSrc": "cirque/cards/fr_solidement_adv.webp"}, {"id": "fr_loyalement_adv", "adv": true, "fr": "loyalement", "g": "adv", "en": "loyally", "ipa": "/lwajaləmɑ̃/", "say": "lwah-yah-luh-MAHN", "hook": "Like English 'loyally', said lwah-yah-luh-MAHN: a dog sits LOYALLY at the foot of the ladder, looking up at her acrobat friend.", "note": null, "ex": ["Il a joué loyalement.", "He played fairly."], "box": [65.2344, 80.5556, 8.5938, 17.3611], "label": [72.1094, 94.3056], "labelPx": [860.0, 679, 126, 29], "boxPx": [835, 580, 110, 125], "side": "C", "cardSrc": "cirque/cards/fr_loyalement_adv.webp"}], "parent": null}, "parade": {"name": "La parade", "room_id": "R_adv_manner_05", "image": "cirque/parade.jpg", "backTo": "cirque", "alt": "The parade loft of the big top, painted in ink and gouache, with a costume rack on the right and a round stand in the middle: a shivering snowman with icicles, a cat in an apron beside a tower of eggs, and the Snow Queen glaring at a little man. A trumpeter plays as two seals cover their ears, a man waters a plant under a glass dome, a clown hands back a wallet, and a gentleman tips his hat. An acrobat tests the trapeze with a toe, a man pushes a boulder uphill, a rude man shoves another, and a penguin sits by a golden trophy. On the floor the ringmaster frowns at a monkey in his top hat, a hippo in a tutu walks a low rope, a clown with half his wig shaved looks in a mirror, and the ringmaster measures a seal with a ruler. The yellow door on the left leads back to the ring.", "nameplate": [88, 95], "doors": [{"to": "cirque", "label": "Le Chapiteau du Cirque", "hint": "Go back through the yellow door to the ring", "hit": [44, 150, 170, 375], "thumb": "cirque/cirque.jpg"}], "zooms": [], "items": [{"id": "fr_affreusement_adv", "adv": true, "fr": "affreusement", "g": "adv", "en": "dreadfully, horribly", "ipa": "/a.fʁøz.mɑ̃/", "say": "ah-freuh-zuh-MAHN", "hook": "A snowman is DREADFULLY frozen (\"ah-FREUH-zuh MAHN\"), shivering HORRIBLY with icicles hanging off him.", "note": null, "ex": ["Je suis affreusement en retard.", "I'm dreadfully late."], "box": [31.25, 4.4444, 10.5469, 20.8333], "label": [36.5234, 1.6667], "labelPx": [393.5, 12, 148, 29], "boxPx": [400, 32, 135, 150], "side": "C", "cardSrc": "cirque/cards/fr_affreusement_adv.webp"}, {"id": "fr_delicatement_adv", "adv": true, "fr": "délicatement", "g": "adv", "en": "delicately", "ipa": "/de.li.kat.mɑ̃/", "say": "day-lee-kah-tuh-MAHN", "hook": "Like English 'delicately', said day-lee-kah-tuh-MAHN: a deli cat in a striped apron DELICATELY steadies a wobbling tower of eggs.", "note": null, "ex": ["Elle pose délicatement le vase.", "She sets the vase down delicately."], "box": [44.5312, 5.5556, 11.7188, 19.4444], "label": [50.3906, 1.6667], "labelPx": [572.0, 12, 146, 29], "boxPx": [570, 40, 150, 140], "side": "C", "cardSrc": "cirque/cards/fr_delicatement_adv.webp"}, {"id": "fr_froidement_adv", "adv": true, "fr": "froidement", "g": "adv", "en": "coldly", "ipa": "/fʁwad.mɑ̃/", "say": "frwah-duh-MAHN", "hook": "The Snow Queen frowns (\"FRWAHD-mahn\") at a little man and glares COLDLY, icicles in the air.", "note": null, "ex": ["Elle m'a accueilli froidement.", "She greeted me coldly."], "box": [57.0312, 3.8889, 12.8906, 21.1111], "label": [63.4766, 1.6667], "labelPx": [749.0, 12, 127, 29], "boxPx": [730, 28, 165, 152], "side": "C", "cardSrc": "cirque/cards/fr_froidement_adv.webp"}, {"id": "fr_horriblement_adv", "adv": true, "fr": "horriblement", "g": "adv", "en": "horribly", "ipa": "/ɔ.ʁi.blə.mɑ̃/", "say": "oh-ree-bluh-MAHN", "hook": "Like English 'horribly', said oh-ree-bluh-MAHN: a trumpet plays HORRIBLY out of tune, and two seals cover their ears with their flippers.", "note": null, "ex": ["J'ai horriblement mal aux dents.", "I have a horrible toothache."], "box": [26.5625, 28.4722, 12.8906, 18.75], "label": [33.0078, 42.6389], "labelPx": [348.5, 307, 148, 29], "boxPx": [340, 205, 165, 135], "side": "C", "cardSrc": "cirque/cards/fr_horriblement_adv.webp"}, {"id": "fr_inutilement_adv", "adv": true, "fr": "inutilement", "g": "adv", "en": "uselessly, unnecessarily", "ipa": "/i.ny.til.mɑ̃/", "say": "ee-new-tee-luh-MAHN", "hook": "A man (\"MON\") waters a plant sealed under a glass dome: quite USELESSLY, of no utility (\"ee-nu-teel\"), the water just runs off into a puddle.", "note": null, "ex": ["Ne t'inquiète pas inutilement.", "Don't worry unnecessarily."], "box": [39.8438, 28.4722, 10.1562, 18.75], "label": [44.9219, 42.6389], "labelPx": [508.5, 307, 133, 29], "boxPx": [510, 205, 130, 135], "side": "C", "cardSrc": "cirque/cards/fr_inutilement_adv.webp"}, {"id": "fr_moralement_adv", "adv": true, "fr": "moralement", "g": "adv", "en": "morally", "ipa": "/mɔ.ʁal.mɑ̃/", "say": "moh-rah-luh-MAHN", "hook": "Like English 'morally', said moh-rah-luh-MAHN: a clown finds a wallet and, MORALLY sure, hands it straight back to the smiling lady.", "note": null, "ex": ["Il se sent moralement responsable.", "He feels morally responsible."], "box": [50.3906, 28.4722, 12.8906, 18.75], "label": [56.8359, 42.6389], "labelPx": [659.0, 307, 137, 29], "boxPx": [645, 205, 165, 135], "side": "C", "cardSrc": "cirque/cards/fr_moralement_adv.webp"}, {"id": "fr_poliment_adv", "adv": true, "fr": "poliment", "g": "adv", "en": "politely", "ipa": "/polimɑ̃/", "say": "poh-lee-MAHN", "hook": "Like English 'politely', said poh-lee-MAHN: a gentleman tips his top hat POLITELY.", "note": null, "ex": ["Il répond poliment.", "He answers politely."], "box": [63.6719, 27.7778, 8.2031, 19.4444], "label": [70.2344, 42.6389], "labelPx": [845.5, 307, 107, 29], "boxPx": [815, 200, 105, 140], "side": "C", "cardSrc": "cirque/cards/fr_poliment_adv.webp"}, {"id": "fr_prudemment_adv", "adv": true, "fr": "prudemment", "g": "adv", "en": "prudently", "ipa": "/pʁy.da.mɑ̃/", "say": "prew-dah-MAHN", "hook": "Like English 'prudently', said prew-dah-MAHN: an acrobat PRUDENTLY tests the trapeze with one toe before swinging.", "note": null, "ex": ["Conduis prudemment sur la neige.", "Drive carefully on the snow."], "box": [25.7812, 49.3056, 8.9844, 18.75], "label": [27.5781, 63.4722], "labelPx": [281.0, 457, 144, 29], "boxPx": [330, 355, 115, 135], "side": "C", "cardSrc": "cirque/cards/fr_prudemment_adv.webp"}, {"id": "fr_peniblement_adv", "adv": true, "fr": "péniblement", "g": "adv", "en": "horribly; awfully; with great difficulty", "ipa": "/pe.ni.blə.mɑ̃/", "say": "pay-nee-bluh-MAHN", "hook": "A man pushes a huge boulder uphill WITH GREAT DIFFICULTY, groaning with pain (\"pay-NEE-bluh\").", "note": null, "ex": ["Il monte péniblement l'escalier.", "He climbs the stairs with difficulty."], "box": [35.1562, 49.3056, 14.0625, 19.4444], "label": [42.1875, 64.1667], "labelPx": [469.5, 462, 141, 29], "boxPx": [450, 355, 180, 140], "side": "C", "cardSrc": "cirque/cards/fr_peniblement_adv.webp"}, {"id": "fr_rudement_adv", "adv": true, "fr": "rudement", "g": "adv", "en": "hard, violently; harshly, roughly", "ipa": "/ʁydəmɑ̃/", "say": "rew-duh-MAHN", "hook": "A rude man (\"rew-duh-MAHN\") shoves another ROUGHLY, who stumbles.", "note": null, "ex": ["C'est rudement bon !", "It's awfully good!"], "box": [49.6094, 49.3056, 10.1562, 19.4444], "label": [54.6875, 64.1667], "labelPx": [642.5, 462, 115, 29], "boxPx": [635, 355, 130, 140], "side": "C", "cardSrc": "cirque/cards/fr_rudement_adv.webp"}, {"id": "fr_solennellement_adv", "adv": true, "fr": "solennellement", "g": "adv", "en": "solemnly", "ipa": "/sɔ.la.nɛl.mɑ̃/", "say": "soh-lah-neh-luh-MAHN", "hook": "Like English 'solemnly', said soh-lah-neh-luh-MAHN: a penguin sits SOLEMNLY on a red velvet cushion beside a golden trophy.", "note": null, "ex": ["Le maire déclare solennellement le pont ouvert.", "The mayor solemnly declares the bridge open."], "box": [62.5, 48.6111, 14.8438, 19.4444], "label": [69.9219, 63.4722], "labelPx": [811.0, 457, 168, 29], "boxPx": [800, 350, 190, 140], "side": "C", "cardSrc": "cirque/cards/fr_solennellement_adv.webp"}, {"id": "fr_severement_adv", "adv": true, "fr": "sévèrement", "g": "adv", "en": "severely; austerely", "ipa": "/se.vɛːʁ.mɑ̃/", "say": "say-veh-ruh-MAHN", "hook": "Like English 'severely', said say-veh-ruh-MAHN: the ringmaster frowns SEVERELY at a monkey wearing his top hat.", "note": null, "ex": ["Il a été sévèrement puni.", "He was severely punished."], "box": [22.6562, 69.4444, 14.8438, 20.8333], "label": [30.0781, 90.8333], "labelPx": [319.5, 654, 131, 29], "boxPx": [290, 500, 190, 150], "side": "C", "cardSrc": "cirque/cards/fr_severement_adv.webp"}, {"id": "fr_gracieusement_adv", "adv": true, "fr": "gracieusement", "g": "adv", "en": "gracefully; elegantly", "ipa": "/ɡʁa.sjøz.mɑ̃/", "say": "grah-syeuh-zuh-MAHN", "hook": "Like English 'gracefully', said grah-syeuh-zuh-MAHN: a hippo in a pink tutu tiptoes GRACEFULLY along a low tightrope.", "note": null, "ex": ["Le musée nous a gracieusement prêté le tableau.", "The museum kindly lent us the painting."], "box": [37.6562, 69.4444, 10.5469, 20.8333], "label": [42.9297, 90.8333], "labelPx": [468.0, 654, 163, 29], "boxPx": [482, 500, 135, 150], "side": "C", "cardSrc": "cirque/cards/fr_gracieusement_adv.webp"}, {"id": "fr_radicalement_adv", "adv": true, "fr": "radicalement", "g": "adv", "en": "radically, in a radical fashion", "ipa": "/ʁa.di.kal.mɑ̃/", "say": "rah-dee-kah-luh-MAHN", "hook": "Like English 'radically', said rah-dee-kah-luh-MAHN: a clown has shaved off half his orange wig: a RADICALLY new look in the mirror.", "note": null, "ex": ["Sa vie a radicalement changé.", "His life has changed radically."], "box": [49.2188, 69.4444, 15.2344, 20.8333], "label": [56.8359, 90.8333], "labelPx": [654.0, 654, 147, 29], "boxPx": [630, 500, 195, 150], "side": "C", "cardSrc": "cirque/cards/fr_radicalement_adv.webp"}, {"id": "fr_rigoureusement_adv", "adv": true, "fr": "rigoureusement", "g": "adv", "en": "rigorously, strictly, thoroughly; absolutely, entirely", "ipa": "/ʁi.ɡu.ʁøz.mɑ̃/", "say": "ree-goo-reuh-zuh-MAHN", "hook": "Like English 'rigorously', said ree-goo-reuh-zuh-MAHN: the ringmaster measures a seal RIGOROUSLY with a long ruler.", "note": null, "ex": ["Il est rigoureusement interdit de nourrir les animaux.", "Feeding the animals is strictly forbidden."], "box": [65.0, 69.4444, 10.0, 20.8333], "label": [73.0, 90.8333], "labelPx": [847.4, 654, 174, 29], "boxPx": [832, 500, 128, 150], "side": "C", "cardSrc": "cirque/cards/fr_rigoureusement_adv.webp"}], "parent": null}, "magie": {"name": "La magie", "room_id": "R_adv_manner_06", "image": "cirque/magie.jpg", "backTo": "cirque", "alt": "The magic loft of the big top, painted in ink and gouache, with a magician's table, top hat and dove cage on the right and a round stand in the middle: a man holds up a grand piano on one finger, a clown hands out balloons to a giraffe, and a cat yawns. Clowns tumble out of a tiny car, a seal sorts a box of balls, a clown slips on a banana peel, and a rabbit hops into a top hat. A tabby loses its fake lion mane, a cat grips a trapeze, an ant sweeps, and a pig fills a piggy bank. On the floor a ball bops a clown's nose, three poodles bow in spotlights, a clown trips over his shoe, and a monkey in a lab coat measures a trampoline. The red door on the left leads back to the ring.", "nameplate": [88, 95], "doors": [{"to": "cirque", "label": "Le Chapiteau du Cirque", "hint": "Go back through the red door to the ring", "hit": [44, 150, 170, 375], "thumb": "cirque/cirque.jpg"}], "zooms": [], "items": [{"id": "fr_aisement_adv", "adv": true, "fr": "aisément", "g": "adv", "en": "easily", "ipa": "/ɛ.ze.mɑ̃/", "say": "ay-zay-MAHN", "hook": "An easy-going man (\"ay-zay-MAHN\") holds a grand piano up EASILY on one finger, whistling.", "note": null, "ex": ["On trouve aisément le chemin.", "The way is easy to find."], "box": [31.25, 4.8611, 10.9375, 20.8333], "label": [36.7188, 1.6667], "labelPx": [416.0, 12, 108, 29], "boxPx": [400, 35, 140, 150], "side": "C", "cardSrc": "cirque/cards/fr_aisement_adv.webp"}, {"id": "fr_gratuitement_adv", "adv": true, "fr": "gratuitement", "g": "adv", "en": "freely, for free; without cause, gratuitously", "ipa": "/ɡʁa.tɥit.mɑ̃/", "say": "grah-twee-tuh-MAHN", "hook": "Like English 'gratuitously', said grah-twee-tuh-MAHN: a clown hands out balloons FOR FREE, and a giraffe helps itself to some.", "note": null, "ex": ["On peut visiter le musée gratuitement.", "You can visit the museum for free."], "box": [43.3594, 3.4722, 14.8438, 22.9167], "label": [50.7812, 1.6667], "labelPx": [576.0, 12, 148, 29], "boxPx": [555, 25, 190, 165], "side": "C", "cardSrc": "cirque/cards/fr_gratuitement_adv.webp"}, {"id": "fr_ouvertement_adv", "adv": true, "fr": "ouvertement", "g": "adv", "en": "openly; overtly", "ipa": "/u.vɛʁ.tə.mɑ̃/", "say": "oo-vehr-tuh-MAHN", "hook": "Like English 'overtly', said oo-vehr-tuh-MAHN: a cat yawns OPENLY, mouth wide open for all to see.", "note": null, "ex": ["Il parle ouvertement de ses problèmes.", "He talks openly about his problems."], "box": [59.7656, 6.25, 8.9844, 19.4444], "label": [64.2578, 1.6667], "labelPx": [751.0, 12, 143, 29], "boxPx": [765, 45, 115, 140], "side": "C", "cardSrc": "cirque/cards/fr_ouvertement_adv.webp"}, {"id": "fr_pele_mele_adv", "adv": true, "fr": "pêle-mêle", "g": "adv", "en": "any old how", "ipa": "/pɛl.mɛl/", "say": "pehl-MEHL", "hook": "Like English 'pell-mell', said pehl-MEHL: clowns tumble out of a tiny car PELL-MELL, any old how.", "note": null, "ex": ["Ses vêtements sont pêle-mêle sur le lit.", "His clothes are all jumbled up on the bed."], "box": [24.2188, 27.0833, 13.125, 20.8333], "label": [30.7812, 43.3333], "labelPx": [336.5, 312, 115, 29], "boxPx": [310, 195, 168, 150], "side": "C", "cardSrc": "cirque/cards/fr_pele_mele_adv.webp"}, {"id": "fr_systematiquement_adv", "adv": true, "fr": "systématiquement", "g": "adv", "en": "systematically", "ipa": "/sis.te.ma.tik.mɑ̃/", "say": "sees-tay-mah-tee-kuh-MAHN", "hook": "Like English 'systematically', said sees-tay-mah-tee-kuh-MAHN: a seal works SYSTEMATICALLY through a box of balls, one after another.", "note": null, "ex": ["Il arrive systématiquement en retard.", "He's always late."], "box": [39.4531, 28.4722, 12.1094, 19.4444], "label": [45.3906, 43.8889], "labelPx": [482.5, 316, 197, 29], "boxPx": [505, 205, 155, 140], "side": "C", "cardSrc": "cirque/cards/fr_systematiquement_adv.webp"}, {"id": "fr_typiquement_adv", "adv": true, "fr": "typiquement", "g": "adv", "en": "typically", "ipa": "/ti.pik.mɑ̃/", "say": "tee-pea-kuh-MAHN", "hook": "Like English 'typically', said teep-kuh-MAHN: TYPICALLY, the clown slips on the banana peel, again tonight.", "note": null, "ex": ["C'est un plat typiquement français.", "It's a typically French dish."], "box": [53.5156, 28.4722, 9.2188, 19.4444], "label": [57.4219, 29.0278], "labelPx": [664.0, 209, 142, 29], "boxPx": [685, 205, 118, 140], "side": "C", "cardSrc": "cirque/cards/fr_typiquement_adv.webp"}, {"id": "fr_volontairement_adv", "adv": true, "fr": "volontairement", "g": "adv", "en": "intentionally, voluntarily", "ipa": "/vɔ.lɔ̃.tɛʁ.mɑ̃/", "say": "voh-lohn-teh-ruh-MAHN", "hook": "Like English 'voluntarily', said voh-lohn-teh-ruh-MAHN: a brave rabbit hops VOLUNTARILY into the magician's top hat.", "note": null, "ex": ["Il a volontairement oublié son devoir.", "He deliberately forgot his homework."], "box": [63.2812, 27.7778, 8.2031, 20.1389], "label": [69.8438, 43.3333], "labelPx": [810.5, 312, 167, 29], "boxPx": [810, 200, 105, 145], "side": "C", "cardSrc": "cirque/cards/fr_volontairement_adv.webp"}, {"id": "fr_artificiellement_adv", "adv": true, "fr": "artificiellement", "g": "adv", "en": "artificially", "ipa": "/aʁ.ti.fi.sjɛl.mɑ̃/", "say": "ahr-tee-fee-syeh-luh-MAHN", "hook": "Like English 'artificially', said ahr-tee-fee-syeh-luh-MAHN: a lion's ARTIFICIAL mane slips off its strap, revealing a sheepish tabby cat.", "note": null, "ex": ["Ce fruit a été mûri artificiellement.", "This fruit was ripened artificially."], "box": [23.4375, 49.3056, 13.2812, 19.4444], "label": [30.0781, 64.1667], "labelPx": [301.0, 462, 168, 29], "boxPx": [300, 355, 170, 140], "side": "C", "cardSrc": "cirque/cards/fr_artificiellement_adv.webp"}, {"id": "fr_consciemment_adv", "adv": true, "fr": "consciemment", "g": "adv", "en": "consciously", "ipa": "/kɔ̃.sja.mɑ̃/", "say": "kohn-syah-MAHN", "hook": "Like English 'consciously', said kohn-syah-MAHN: a trapeze cat chooses each grip CONSCIOUSLY, eyes wide open, fully awake.", "note": null, "ex": ["Il l'a fait consciemment.", "He did it consciously."], "box": [37.1094, 50.0, 10.3125, 19.4444], "label": [43.3594, 50.5556], "labelPx": [475.0, 364, 160, 29], "boxPx": [475, 360, 132, 140], "side": "C", "cardSrc": "cirque/cards/fr_consciemment_adv.webp"}, {"id": "fr_consciencieusement_adv", "adv": true, "fr": "consciencieusement", "g": "adv", "en": "conscientiously", "ipa": "/kɔ̃.sjɑ̃.sjøz.mɑ̃/", "say": "kohn-syahn-syeuh-zuh-MAHN", "hook": "Like English 'conscientiously', said kohn-syahn-syeuh-zuh-MAHN: an ant sweeps every grain of sawdust CONSCIENTIOUSLY.", "note": null, "ex": ["Il fait consciencieusement ses devoirs.", "He does his homework conscientiously."], "box": [50.0, 50.0, 12.8906, 18.75], "label": [56.0938, 64.7222], "labelPx": [611.0, 466, 214, 29], "boxPx": [640, 360, 165, 135], "side": "C", "cardSrc": "cirque/cards/fr_consciencieusement_adv.webp"}, {"id": "fr_financierement_adv", "adv": true, "fr": "financièrement", "g": "adv", "en": "financially", "ipa": "/fi.nɑ̃.sjɛʁ.mɑ̃/", "say": "fee-nahn-syeh-ruh-MAHN", "hook": "Like English 'financially', said fee-nahn-syeh-ruh-MAHN: a pig counts coins into a piggy bank: FINANCIALLY, the circus is saved.", "note": null, "ex": ["Ses parents l'aident financièrement.", "His parents help him financially."], "box": [64.8438, 50.0, 10.3125, 18.75], "label": [73.0938, 64.1667], "labelPx": [852.6, 462, 166, 29], "boxPx": [830, 360, 132, 135], "side": "C", "cardSrc": "cirque/cards/fr_financierement_adv.webp"}, {"id": "fr_indirectement_adv", "adv": true, "fr": "indirectement", "g": "adv", "en": "indirectly", "ipa": "/ɛ̃.di.ʁɛk.tə.mɑ̃/", "say": "an-dee-rehk-tuh-MAHN", "hook": "Like English 'indirectly', said an-dee-rehk-tuh-MAHN: a ball bounces round INDIRECTLY before bopping the clown on the nose.", "note": null, "ex": ["Il m'a répondu indirectement.", "He answered me indirectly."], "box": [23.4375, 70.1389, 13.6719, 20.8333], "label": [30.2734, 91.5278], "labelPx": [309.5, 659, 156, 29], "boxPx": [300, 505, 175, 150], "side": "C", "cardSrc": "cirque/cards/fr_indirectement_adv.webp"}, {"id": "fr_individuellement_adv", "adv": true, "fr": "individuellement", "g": "adv", "en": "individually; personally", "ipa": "/ɛ̃.di.vi.dɥɛl.mɑ̃/", "say": "an-dee-vee-dweh-luh-MAHN", "hook": "Like English 'individually', said an-dee-vee-dweh-luh-MAHN: three poodles bow INDIVIDUALLY, each in its own spotlight.", "note": null, "ex": ["Le professeur parle à chaque élève individuellement.", "The teacher speaks to each pupil individually."], "box": [37.3438, 70.1389, 13.2812, 20.8333], "label": [43.9844, 91.5278], "labelPx": [471.5, 659, 183, 29], "boxPx": [478, 505, 170, 150], "side": "C", "cardSrc": "cirque/cards/fr_individuellement_adv.webp"}, {"id": "fr_intentionnellement_adv", "adv": true, "fr": "intentionnellement", "g": "adv", "en": "intentionally; deliberately; on purpose", "ipa": "/ɛ̃.tɑ̃.sjɔ.nɛl.mɑ̃/", "say": "an-tahn-syoh-neh-luh-MAHN", "hook": "Like English 'intentionally', said an-tahn-syoh-neh-luh-MAHN: a clown trips over his own big shoe ON PURPOSE, grinning and waving at the crowd.", "note": null, "ex": ["Il a intentionnellement laissé la porte ouverte.", "He intentionally left the door open."], "box": [51.1719, 70.1389, 12.3438, 20.8333], "label": [61.0469, 91.5278], "labelPx": [678.9, 659, 205, 29], "boxPx": [655, 505, 158, 150], "side": "C", "cardSrc": "cirque/cards/fr_intentionnellement_adv.webp"}, {"id": "fr_scientifiquement_adv", "adv": true, "fr": "scientifiquement", "g": "adv", "en": "scientifically", "ipa": "/sjɑ̃.ti.fik.mɑ̃/", "say": "syahn-tee-fee-kuh-MAHN", "hook": "Like English 'scientifically', said syahn-tee-fee-kuh-MAHN: a monkey in a lab coat SCIENTIFICALLY measures the trampoline with a measuring stick.", "note": null, "ex": ["C'est scientifiquement prouvé.", "It's scientifically proven."], "box": [63.6719, 70.1389, 12.6562, 20.8333], "label": [73.7969, 86.3889], "labelPx": [853.6, 622, 182, 29], "boxPx": [815, 505, 162, 150], "side": "C", "cardSrc": "cirque/cards/fr_scientifiquement_adv.webp"}], "parent": null}, "surprises": {"name": "Les surprises", "room_id": "R_adv_manner_07", "image": "cirque/surprises.jpg", "backTo": "cirque", "alt": "The surprises loft of the big top, painted in ink and gouache, with a pile of gift boxes and a jack-in-the-box on the right and a round stand in the middle: a bear juggles clubs and a sandwich, a baker carries a steaming loaf, and a magician's dove vanishes in smoke. An elephant in a tutu stands by a lamp, a boy drives a toy train on its rails, three acrobats leap together, and a cannon fires a clown with popcorn. Spectators dance a conga by conga drums, a girl jumps back from a beetroot in her soup, a snowman serenades a pear, and a pony squeezes between hay bales. On the floor a keeper rushes fish to a tiger, a tightrope walker stares ahead, a confetti cannon covers a clown, and an umbrella props up a cracked tent pole. The green door on the left leads back to the ring.", "nameplate": [88, 95], "doors": [{"to": "cirque", "label": "Le Chapiteau du Cirque", "hint": "Go back through the green door to the ring", "hit": [38, 148, 175, 375], "thumb": "cirque/cirque.jpg"}], "zooms": [], "items": [{"id": "fr_distraitement_adv", "adv": true, "fr": "distraitement", "g": "adv", "en": "absent-mindedly", "ipa": "/dis.tʁɛt.mɑ̃/", "say": "dees-treh-tuh-MAHN", "hook": "Like English 'distractedly', said dees-treh-tuh-MAHN: a bear in a striped shirt juggles DISTRACTEDLY, and his lunch sandwich has ended up in the air with the clubs.", "note": null, "ex": ["Il écoute distraitement.", "He listens absent-mindedly."], "box": [30.8594, 4.8611, 11.3281, 20.8333], "label": [36.5234, 1.6667], "labelPx": [392.0, 12, 151, 29], "boxPx": [395, 35, 145, 150], "side": "C", "cardSrc": "cirque/cards/fr_distraitement_adv.webp"}, {"id": "fr_fraichement_adv", "adv": true, "fr": "fraîchement", "g": "adv", "en": "freshly", "ipa": "/fʁɛʃ.mɑ̃/", "say": "freh-shuh-MAHN", "hook": "A fresh-faced baker (\"freh-shuh-MAHN\") carries a loaf FRESHLY baked, still steaming.", "note": null, "ex": ["Les murs sont fraîchement peints.", "The walls are freshly painted."], "box": [43.75, 5.5556, 10.9375, 20.1389], "label": [49.2188, 1.6667], "labelPx": [561.0, 12, 138, 29], "boxPx": [560, 40, 140, 145], "side": "C", "cardSrc": "cirque/cards/fr_fraichement_adv.webp"}, {"id": "fr_instantanement_adv", "adv": true, "fr": "instantanément", "g": "adv", "en": "instantaneously", "ipa": "/ɛ̃s.tɑ̃.ta.ne.mɑ̃/", "say": "ans-tahn-tah-nay-MAHN", "hook": "Like English 'instantaneously', said ans-tahn-tah-nay-MAHN: the magician snaps his fingers and the dove vanishes INSTANTLY, leaving only a curl of white magic mist in the air.", "note": null, "ex": ["Le chat s'est endormi instantanément.", "The cat fell asleep instantly."], "box": [56.6406, 4.1667, 12.5, 20.8333], "label": [62.8906, 1.6667], "labelPx": [719.0, 12, 172, 29], "boxPx": [725, 30, 160, 150], "side": "C", "cardSrc": "cirque/cards/fr_instantanement_adv.webp"}, {"id": "fr_momentanement_adv", "adv": true, "fr": "momentanément", "g": "adv", "en": "momentarily", "ipa": "/mɔ.mɑ̃.ta.ne.mɑ̃/", "say": "moh-mahn-tah-nay-MAHN", "hook": "Like English 'momentarily', said moh-mahn-tah-nay-MAHN: the lamp went out MOMENTARILY, and when it flicked back on the elephant was wearing a pink tutu.", "note": null, "ex": ["Le service est momentanément interrompu.", "The service is temporarily interrupted."], "box": [25.7812, 27.0833, 12.5, 20.8333], "label": [28.2812, 43.3333], "labelPx": [270.5, 312, 183, 29], "boxPx": [330, 195, 160, 150], "side": "C", "cardSrc": "cirque/cards/fr_momentanement_adv.webp"}, {"id": "fr_parallelement_adv", "adv": true, "fr": "parallèlement", "g": "adv", "en": "parallelly; at the same time", "ipa": "/pa.ʁa.lɛl.mɑ̃/", "say": "pah-rah-leh-luh-MAHN", "hook": "Like English 'parallel', said pah-rah-lehl-MAHN: a boy drives his toy train along two PARALLEL rails that never meet.", "note": null, "ex": ["Il étudie et, parallèlement, il travaille.", "He studies and works at the same time."], "box": [39.0625, 27.7778, 11.3281, 20.8333], "label": [44.6875, 28.3333], "labelPx": [495.0, 204, 154, 29], "boxPx": [500, 200, 145, 150], "side": "C", "cardSrc": "cirque/cards/fr_parallelement_adv.webp"}, {"id": "fr_simultanement_adv", "adv": true, "fr": "simultanément", "g": "adv", "en": "simultaneously", "ipa": "/si.myl.ta.ne.mɑ̃/", "say": "see-mewl-tah-nay-MAHN", "hook": "Like English 'simultaneously', said see-mewl-tah-nay-MAHN: three acrobats leap SIMULTANEOUSLY, all in mid-air at the same moment.", "note": null, "ex": ["Ils ont parlé simultanément.", "They spoke at the same time."], "box": [51.1719, 27.0833, 11.3281, 20.8333], "label": [57.2656, 44.0278], "labelPx": [650.5, 317, 165, 29], "boxPx": [655, 195, 145, 150], "side": "C", "cardSrc": "cirque/cards/fr_simultanement_adv.webp"}, {"id": "fr_soudainement_adv", "adv": true, "fr": "soudainement", "g": "adv", "en": "suddenly", "ipa": "/su.dɛn.mɑ̃/", "say": "soo-deh-nuh-MAHN", "hook": "Like English 'suddenly', said soo-deh-nuh-MAHN: SUDDENLY the cannon fires with a puff, and a clown pops out, still clutching his popcorn.", "note": null, "ex": ["Il s'est mis à pleuvoir soudainement.", "It suddenly started to rain."], "box": [64.2188, 27.0833, 11.5625, 20.8333], "label": [73.4688, 43.3333], "labelPx": [862.4, 312, 156, 29], "boxPx": [822, 195, 148, 150], "side": "C", "cardSrc": "cirque/cards/fr_soudainement_adv.webp"}, {"id": "fr_spontanement_adv", "adv": true, "fr": "spontanément", "g": "adv", "en": "spontaneously", "ipa": "/spɔ̃tanemɑ̃/", "say": "spohn-tah-nay-MAHN", "hook": "Like English 'spontaneously', said spohn-tah-nay-MAHN: the audience SPONTANEOUSLY breaks into a conga, dancing round the conga drums.", "note": null, "ex": ["Elle a spontanément proposé son aide.", "She spontaneously offered to help."], "box": [23.8281, 50.0, 12.8906, 20.1389], "label": [30.2734, 65.5556], "labelPx": [308.5, 472, 158, 29], "boxPx": [305, 360, 165, 145], "side": "C", "cardSrc": "cirque/cards/fr_spontanement_adv.webp"}, {"id": "fr_subitement_adv", "adv": true, "fr": "subitement", "g": "adv", "en": "suddenly", "ipa": "/sy.bit.mɑ̃/", "say": "sew-bee-tuh-MAHN", "hook": "SUDDENLY a beetroot pops up out of the soup in front of Sue (\"sew-beet-MAHN\"), and she jumps a mile.", "note": null, "ex": ["Le chien s'est arrêté subitement.", "The dog suddenly stopped."], "box": [37.1094, 50.0, 12.5, 20.1389], "label": [43.3594, 65.5556], "labelPx": [490.5, 472, 129, 29], "boxPx": [475, 360, 160, 145], "side": "C", "cardSrc": "cirque/cards/fr_subitement_adv.webp"}, {"id": "fr_eperdument_adv", "adv": true, "fr": "éperdument", "g": "adv", "en": "desperately; passionately; utterly", "ipa": "/e.pɛʁ.dy.mɑ̃/", "say": "ay-pehr-dew-MAHN", "hook": "A snowman (\"MAHN\") is DESPERATELY, PASSIONATELY in love with a pear (\"ay-PEHR\") glistening with dew (\"DEW\"), and serenades it on his guitar.", "note": null, "ex": ["Il est éperdument amoureux.", "He's head over heels in love."], "box": [50.3906, 50.0, 12.5, 20.1389], "label": [56.6406, 65.5556], "labelPx": [656.5, 472, 137, 29], "boxPx": [645, 360, 160, 145], "side": "C", "cardSrc": "cirque/cards/fr_eperdument_adv.webp"}, {"id": "fr_etroitement_adv", "adv": true, "fr": "étroitement", "g": "adv", "en": "narrowly", "ipa": "/e.tʁwat.mɑ̃/", "say": "ay-trwah-tuh-MAHN", "hook": "A pony at a trot (\"ay-TRWAHT-mahn\") squeezes NARROWLY between two hay bales, its sides just brushing them.", "note": null, "ex": ["Les deux affaires sont étroitement liées.", "The two matters are closely linked."], "box": [63.2812, 50.0, 13.2812, 19.4444], "label": [69.9219, 50.5556], "labelPx": [827.5, 364, 135, 29], "boxPx": [810, 360, 170, 140], "side": "C", "cardSrc": "cirque/cards/fr_etroitement_adv.webp"}, {"id": "fr_imperativement_adv", "adv": true, "fr": "impérativement", "g": "adv", "en": "urgently; imperatively", "ipa": "/ɛ̃.pe.ʁa.tiv.mɑ̃/", "say": "an-pay-rah-tee-vuh-MAHN", "hook": "Like English 'imperatively', said an-pay-rah-tee-vuh-MAHN: the tiger must be fed IMPERATIVELY now, so the keeper rushes over with a bucket of fish.", "note": null, "ex": ["Vous devez impérativement arriver à l'heure.", "You absolutely must arrive on time."], "box": [23.4375, 70.8333, 13.2812, 20.8333], "label": [26.0938, 92.2222], "labelPx": [247.5, 664, 173, 29], "boxPx": [300, 510, 170, 150], "side": "C", "cardSrc": "cirque/cards/fr_imperativement_adv.webp"}, {"id": "fr_intensement_adv", "adv": true, "fr": "intensément", "g": "adv", "en": "intensely", "ipa": "/ɛ̃.tɑ̃.se.mɑ̃/", "say": "an-tahn-say-MAHN", "hook": "Like English 'intensely', said an-tahn-say-MAHN: a tightrope walker on a low rope stares INTENSELY ahead.", "note": null, "ex": ["Il vit chaque moment intensément.", "He lives each moment intensely."], "box": [37.1094, 70.8333, 12.5, 20.8333], "label": [43.3594, 92.2222], "labelPx": [484.5, 664, 141, 29], "boxPx": [475, 510, 160, 150], "side": "C", "cardSrc": "cirque/cards/fr_intensement_adv.webp"}, {"id": "fr_prematurement_adv", "adv": true, "fr": "prématurément", "g": "adv", "en": "prematurely; untimely", "ipa": "/pʁematyʁemɑ̃/", "say": "pray-mah-tew-ray-MAHN", "hook": "Like English 'prematurely', said pray-mah-tew-ray-MAHN: the confetti cannon fires PREMATURELY, covering a startled clown before the act.", "note": null, "ex": ["Le bébé est né prématurément.", "The baby was born prematurely."], "box": [50.3906, 70.8333, 12.8906, 20.8333], "label": [56.6406, 92.2222], "labelPx": [639.5, 664, 171, 29], "boxPx": [645, 510, 165, 150], "side": "C", "cardSrc": "cirque/cards/fr_prematurement_adv.webp"}, {"id": "fr_temporairement_adv", "adv": true, "fr": "temporairement", "g": "adv", "en": "temporarily", "ipa": "/tɑ̃.pɔ.ʁɛʁ.mɑ̃/", "say": "tahn-poh-reh-ruh-MAHN", "hook": "Like English 'temporarily', said tahn-poh-reh-ruh-MAHN: a cracked, taped-up tent pole is held up TEMPORARILY by an open umbrella until the new one arrives.", "note": null, "ex": ["Le musée est temporairement fermé.", "The museum is temporarily closed."], "box": [63.6719, 69.4444, 12.5, 22.9167], "label": [73.6719, 78.8889], "labelPx": [854.5, 568.0, 177, 29], "boxPx": [815, 500, 160, 165], "side": "C", "cardSrc": "cirque/cards/fr_temporairement_adv.webp"}], "parent": null}}, "building_id": "B55_cirque", "sector_id": "S16_park", "v1_room_id": "R_adv_manner_01"};
